// Collection variables pattern per: Postman Inc., "Variables," Postman Learning Center, 2025.
// https://learning.postman.com/docs/sending-requests/variables/variables/
// [Accessed: 06-Oct-2026].

// The producer must answer 202 Accepted because the order is only queued, not processed yet
pm.test("Order accepted (202)", function () {
    pm.response.to.have.status(202);
});

// The reply must contain the order id so the next requests can find the order
pm.test("Reply contains orderId and orderDate", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("orderId");
    pm.expect(json).to.have.property("orderDate");
});

// Save the id and the date (yyyy-MM-dd, the PartitionKey) for the next requests
pm.test("Order id and date saved for the next requests", function () {
    const json = pm.response.json();
    pm.collectionVariables.set("statusOrderId", json.orderId);
    pm.collectionVariables.set("statusOrderDate", String(json.orderDate).substring(0, 10));
    pm.expect(pm.collectionVariables.get("statusOrderId")).to.not.be.empty;
});

// Test script attribution: pattern adapted from Postman's official documentation:
// Postman Inc., "Write scripts to test API responses," Postman Learning Center, 2025.
// https://learning.postman.com/docs/tests-and-scripts/write-scripts/test-scripts/
// [Accessed: 06-Oct-2026].

// A valid next step (Received to Preparing) must return 200 OK
pm.test("Status updated (200)", function () {
    pm.response.to.have.status(200);
});

// The reply uses OrderResponse, so the property names start with capital letters
pm.test("Order is now Preparing", function () {
    pm.expect(pm.response.json().Status).to.eql("Preparing");
});

pm.test("Reply is for the same order", function () {
    pm.expect(pm.response.json().OrderId).to.eql(pm.collectionVariables.get("statusOrderId"));
});

// Test script attribution: pattern adapted from Postman's official documentation:
// Postman Inc., "Write scripts to test API responses," Postman Learning Center, 2025.
// https://learning.postman.com/docs/tests-and-scripts/write-scripts/test-scripts/
// [Accessed: 06-Oct-2026].

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// The order may have moved on by itself, so any of the later statuses is correct
pm.test("Order status is a valid status", function () {
    pm.expect(pm.response.json().Status).to.be.oneOf(["Preparing", "Ready", "Collected"]);
});

// Test script attribution: pattern adapted from Postman's official documentation:
// Postman Inc., "Write scripts to test API responses," Postman Learning Center, 2025.
// https://learning.postman.com/docs/tests-and-scripts/write-scripts/test-scripts/
// [Accessed: 06-Oct-2026].

// A bad status or a bad body must be rejected with 400 Bad Request
pm.test("Bad request (400)", function () {
    pm.response.to.have.status(400);
});

// The function replies with { "error": "..." } so the user knows what went wrong
pm.test("Response explains the problem", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("error");
    pm.expect(json.error).to.be.a("string").and.not.be.empty;
});

